/**
 * Generates the catalog migration (templates + country rules) from the TypeScript sources of truth,
 * so the database catalog can never drift from @gars/template-engine and @gars/country-rules.
 */
import { listCountryRules } from "@gars/country-rules";
import { TEMPLATES } from "@gars/template-engine";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

export function catalogSql(): string {
  const lines: string[] = [
    "-- GENERATED by `pnpm gen:catalog` from packages/template-engine + packages/country-rules. DO NOT EDIT BY HAND.",
    "-- Templates are published (all 105 render in tests). Country rules stay 'draft' until a human review marks them reviewed.",
    "",
    "insert into public.resume_templates (id, name, category, status, supports_rtl, supports_docx, is_premium) values",
    TEMPLATES.map((t) => `  (${q(t.id)}, ${q(t.name)}, ${q(t.category)}, 'published', ${t.supportsRtl}, ${t.supportsDocx}, ${t.premium})`).join(",\n"),
    "on conflict (id) do update set name = excluded.name, category = excluded.category, supports_rtl = excluded.supports_rtl,",
    "  supports_docx = excluded.supports_docx, is_premium = excluded.is_premium;",
    "",
    "insert into public.template_versions (template_id, version_no, spec, published_at) values",
    TEMPLATES.map((t) => `  (${q(t.id)}, 1, ${j(t)}, now())`).join(",\n"),
    "on conflict (template_id, version_no) do update set spec = excluded.spec;",
    "",
    "insert into public.country_rules (country_code, name, config, status, last_reviewed_on) values",
    listCountryRules().map((r) => `  (${q(r.countryCode)}, ${q(r.name)}, ${j(r)}, 'draft', ${q(r.lastReviewed)})`).join(",\n"),
    "on conflict (country_code) do update set name = excluded.name, config = excluded.config, last_reviewed_on = excluded.last_reviewed_on;",
    "",
    "delete from public.country_rule_sources where country_code in (select country_code from public.country_rules);",
    "insert into public.country_rule_sources (country_code, title, url) values",
    listCountryRules().flatMap((r) => r.sources.map((s) => `  (${q(r.countryCode)}, ${q(s.title)}, ${q(s.url)})`)).join(",\n") + ";",
    "",
  ];
  return lines.join("\n");
}
